                  branch: {
                    anyOf: [
                      {
                        $ref: '#/$defs/AgentSessionBranch',
                      },
                      {
                        type: 'null',
                      },
                    ],
                  },
                  backend: {
                    anyOf: [
                      {
                        $ref: '#/$defs/AgentBackendPreference',
                      },
                      {
                        type: 'null',
                      },
                    ],
                  },
                  tools: {
                    type: ['array', 'null'],
                    items: {
                      type: 'string',
                    },
                  },
