                      attemptId: {
                        $ref: '#/$defs/ModelAttemptId',
                      },
                      messageId: {
                        type: 'string',
                      },
                      ordinal: {
                        type: 'integer',
                        format: 'uint64',
                        minimum: 0,
                      },
